import {ITEM_TYPES,CONTAINERS,TIERS,TIER_NAMES,itemArtKey} from './items.js?v=21';

export function normalizeMaterials(value){return Object.fromEntries(['blueprint','data'].map(kind=>[kind,Number.isFinite(Number(value?.[kind]))?Math.max(0,Math.floor(Number(value[kind]))):0]));}
function icon(meta,atlas,label,size=32){if(!meta||!atlas)return '';const ratio=size/atlas.cell;return `<span class="item-art" role="img" aria-label="${label}" style="width:${size}px;height:${size}px;background-image:url('${meta.src}');background-size:${atlas.width*ratio}px ${atlas.height*ratio}px;background-position:-${meta.x*ratio}px -${meta.y*ratio}px"></span>`;}
export function itemsHtml(manifest,materials){const pack=manifest?.items;if(!pack)return '<p class="modal-note">准备飞行资源</p>';const stored=normalizeMaterials(materials);return `<p class="modal-note">28 款物品，按小型、中型、大型区分。靠近物品后会自动吸附。</p><div class="material-wallet"><span>蓝图材料 <b>${stored.blueprint}</b></span><span>回声数据 <b>${stored.data}</b></span></div><div class="item-codex">${ITEM_TYPES.map(item=>`<article class="item-card"><h3>${item.label}</h3><div class="item-variants">${(item.single?['l']:TIERS).map(tier=>`<div>${icon(pack.sprites[itemArtKey(item.kind,tier)],pack.atlases.static,item.label+(item.single?'':' · '+TIER_NAMES[tier]))}<small>${item.single?'完整':TIER_NAMES[tier]}</small></div>`).join('')}</div><p>${item.note[0]}</p></article>`).join('')}</div><span class="selection-label">补给与奖励</span><div class="item-codex">${CONTAINERS.map(container=>`<article class="item-card container-card">${icon(pack.effects[container.art],pack.atlases.effects,container.name[0],44)}<h3>${container.name[0]}</h3><p>${container.note[0]}</p></article>`).join('')}</div>`;}
export function materialReportHtml(materials){const gained=normalizeMaterials(materials);if(!gained.blueprint&&!gained.data)return '';return `<div class="material-wallet"><span>蓝图材料 <b>+ ${gained.blueprint}</b></span><span>回声数据 <b>+ ${gained.data}</b></span></div>`;}
